import zipfile, xml.etree.ElementTree as ET

docx_path = '/Users/dudu/Documents/3_Project/12_PxFquery/3_phase_digestion/goal_citation_research/task_pending_t017/1_asset/WXY manuscript_v8.docx'
with zipfile.ZipFile(docx_path) as z:
    xml = z.read('word/document.xml')

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
root = ET.fromstring(xml)
paras = root.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p')
ref_found = False
refs = []
for p in paras:
    texts = []
    for t in p.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t'):
        if t.text:
            texts.append(t.text)
    full = ''.join(texts).strip()
    if full == 'References':
        ref_found = True
        continue
    if ref_found:
        if full.startswith('Figure') or full.startswith('Table') or full.startswith('Supplement') or full == '':
            continue
        refs.append(full)
        if len(refs) >= 15:
            break

print(f'Total refs extracted: {len(refs)}')
for i, r in enumerate(refs, 1):
    print(f'[{i}] {r[:200]}')
